const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define region - northern Madagascar (lat -15 to -12)
  const region = ee.Geometry.Rectangle([43.0, -15.0, 51.0, -12.0]);

  // 2. Get CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // 3. Target period: Dec 2018 + Jan 2019
  const target = chirps
    .filter(ee.Filter.date('2018-12-01', '2019-02-01'))
    .select('precipitation');

  const targetSize = target.size().getInfo();
  console.log(`Target period images: ${targetSize}`);

  if (targetSize === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate total precipitation for target period
  const targetSum = target.sum();
  const targetResult = targetSum.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  });

  const targetRain = targetResult.get('precipitation').getInfo();

  if (targetRain === null || targetRain === undefined) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 5. Calculate long-term average for Dec+Jan (2000-2019)
  let totalLongterm = 0;
  let yearCount = 0;

  for (let year = 2000; year <= 2019; year++) {
    const decStart = `${year}-12-01`;
    const janEnd = `${year + 1}-02-01`;

    const yearCol = chirps
      .filter(ee.Filter.date(decStart, janEnd))
      .select('precipitation');

    const yearSize = yearCol.size().getInfo();

    if (yearSize > 0) {
      const yearSum = yearCol.sum();
      const yearResult = yearSum.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 5000,
        maxPixels: 1e9
      });

      const yearRain = yearResult.get('precipitation').getInfo();

      if (yearRain !== null && yearRain !== undefined) {
        totalLongterm += yearRain;
        yearCount++;
      }
    }
  }

  if (yearCount === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  const longtermAvg = totalLongterm / yearCount;

  // 6. Print evidence and answer
  console.log(`Dec2018-Jan2019 rainfall: ${targetRain.toFixed(2)} mm`);
  console.log(`Long-term avg (2000-2019): ${longtermAvg.toFixed(2)} mm`);
  console.log(`Years analyzed: ${yearCount}`);
  console.log(`Difference: ${(targetRain - longtermAvg).toFixed(2)} mm`);

  if (targetRain < longtermAvg) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
